[CmdletBinding()]param()
$ErrorActionPreference='Stop'
$workspace=Split-Path -Parent $PSScriptRoot
$change='verify-superdesktop-m0';$root=Join-Path $workspace "openspec/changes/$change";$evidence=Join-Path $root 'evidence'
$utf8=[Text.UTF8Encoding]::new($false);$now=[DateTime]::UtcNow.ToString('o');$revision=(& git -C $workspace rev-parse --short=8 HEAD).Trim()
Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class M0GuiResources { [DllImport("user32.dll")] public static extern uint GetGuiResources(IntPtr process, uint flags); }'
function Write-Text([string]$Path,[string]$Text){New-Item -ItemType Directory -Force (Split-Path -Parent $Path)|Out-Null;[IO.File]::WriteAllText($Path,$Text,$utf8)}
function Write-Json([string]$Path,$Value){Write-Text $Path (($Value|ConvertTo-Json -Depth 12)+"`n")}
function Invoke-Checked([string]$Name,[scriptblock]$Command){$prior=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$text=(& $Command 2>&1|Out-String);$exit=$LASTEXITCODE}finally{$ErrorActionPreference=$prior};if($exit-ne0){throw "$Name failed`n$text"};return $text}
foreach($group in @('1.1','1.2','2.1','2.2','2.3','2.4','3.1','3.2','4.1','4.2','4.3','5.1','5.2','5.3')){New-Item -ItemType Directory -Force (Join-Path $evidence "artifacts/$group")|Out-Null}

# 1.1: immutable profile and active (not archived) production lineage.
$platformEvidence=Join-Path $workspace 'openspec/changes/validate-superdesktop-windows-platform/evidence'
$profile=Get-Content -Raw -Encoding UTF8 (Join-Path $platformEvidence 'artifacts/1.1/frozen-profile-contract.json')|ConvertFrom-Json
$os=Get-CimInstance Win32_OperatingSystem;$ubr=(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion').UBR;$fullBuild="$($os.BuildNumber).$ubr"
$reference=Join-Path $platformEvidence 'artifacts/1.1/reference-taskbar.jpg';$referenceHash=(Get-FileHash $reference -Algorithm SHA256).Hash
if($fullBuild-ne'26200.8875'-or$referenceHash-ne'48B5F990B9E155C5C2719D8F8B41D88ED4420A46C3B6018278511F9C349B387E'){throw 'reference profile drift'}
$children=@('validate-superdesktop-windows-platform','build-superdesktop-shell-core','build-superdesktop-gpui-desktop','build-superdesktop-gpui-taskbar','integrate-superexplorer-process-bridge','add-superdesktop-shell-takeover-recovery')
$lineage=@();foreach($child in $children){$dir=Join-Path $workspace "openspec/changes/$child";$manifest=Get-ChildItem (Join-Path $dir 'evidence/artifacts') -Recurse -Filter '*manifest*.json'|Sort-Object FullName|Select-Object -Last 1;$handoff=Get-ChildItem (Join-Path $dir 'evidence/handoffs') -Filter '*.json'|Select-Object -Last 1;$validation=Invoke-Checked "strict $child" {openspec validate $child --strict};$evidenceValidation=Invoke-Checked "evidence $child" {powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $workspace 'scripts/validate-evidence.ps1') -Change $child};$lineage+=[ordered]@{change=$child;state='active-complete-archive-deferred-by-user';manifest=$manifest.FullName.Substring($workspace.Length+1).Replace('\','/');manifest_sha256=(Get-FileHash $manifest.FullName -Algorithm SHA256).Hash;handoff_sha256=(Get-FileHash $handoff.FullName -Algorithm SHA256).Hash;strict='passed';evidence_validator='passed'}}
$baselineContract=[ordered]@{schema='m0-reference-baseline/v1';frozen_before_candidates=$true;windows_build=$fullBuild;explorerpatcher_version='26100.8457.70.3';profile_sha256=(Get-FileHash (Join-Path $platformEvidence 'artifacts/1.1/frozen-profile-contract.json') -Algorithm SHA256).Hash;settings_export_sha256=(Get-FileHash (Join-Path $platformEvidence 'artifacts/1.1/explorerpatcher-profile.json') -Algorithm SHA256).Hash;reference_image_sha256=$referenceHash;tolerance=@{base_physical_px=2;scaled='round(2*dpi/96)';minimum_ssim=0.95;exact_control_state=$true;masks=@(@{name='fixture-window-titles';rect=@(96,0,3304,140)},@{name='time-date-notifications';rect=@(3400,0,437,140)})};correction_disposition=@{adjustment_id='B-W6-REFERENCE-MASK-001';classification='B';reason='The frozen screenshot task fixture begins at x=96 and extends to the x=3400 status boundary; the v1 x=150..2650 rectangle retained live task titles and excluded part of the declared fixture region.';threshold_unchanged=0.95;reference_image_unchanged=$true;exact_control_state_unchanged=$true};production_lineage=$lineage;archive_precondition='blocked-by-explicit-user-no-archive'}
Write-Json (Join-Path $evidence 'artifacts/1.1/reference-baseline.json') $baselineContract

# 1.2: quality and isolated offline build.
$logSummary=@();foreach($gate in @(@('fmt',{cargo fmt --all -- --check}),@('check',{cargo check --workspace --all-targets --locked --offline}),@('clippy',{cargo clippy --workspace --all-targets --locked --offline -- -D warnings}),@('tests',{cargo test --workspace --all-targets --locked --offline}),@('release',{cargo build --workspace --all-targets --release --locked --offline}))){$name=[string]$gate[0];$text=Invoke-Checked $name $gate[1];$logPath=Join-Path $evidence "artifacts/1.2/$name.log";Write-Text $logPath ($text.TrimEnd()+"`n");$logSummary+=[ordered]@{name=$name;exit_status=0;path="evidence/artifacts/1.2/$name.log";sha256=(Get-FileHash $logPath -Algorithm SHA256).Hash}}
$isolated=Join-Path $env:TEMP ("superdesktop-cargo-home-$PID");New-Item -ItemType Directory -Force $isolated|Out-Null;$oldCargo=$env:CARGO_HOME;$env:CARGO_HOME=$isolated;try{$offlineLog=Invoke-Checked 'isolated offline' {cargo build --workspace --all-targets --release --locked --offline}}finally{if($null-eq$oldCargo){Remove-Item Env:CARGO_HOME -ErrorAction SilentlyContinue}else{$env:CARGO_HOME=$oldCargo};$resolved=(Resolve-Path $isolated).Path;if($resolved.StartsWith([IO.Path]::GetTempPath())-and(Split-Path -Leaf $resolved)-like'superdesktop-cargo-home-*'){Remove-Item -LiteralPath $resolved -Recurse -Force}};$offlinePath=Join-Path $evidence 'artifacts/1.2/isolated-offline.log';Write-Text $offlinePath ($offlineLog.TrimEnd()+"`n");$logSummary+=[ordered]@{name='isolated-offline';exit_status=0;path='evidence/artifacts/1.2/isolated-offline.log';sha256=(Get-FileHash $offlinePath -Algorithm SHA256).Hash}
$binaries=@();foreach($path in @('target/release/superdesktop-app.exe','target/release/superdesktop-guardian.exe','target/release/examples/lifecycle_probe.exe')){$full=Join-Path $workspace $path;$binaries+=[ordered]@{path=$path;sha256=(Get-FileHash $full -Algorithm SHA256).Hash;bytes=(Get-Item $full).Length}}
$provenance=Invoke-Checked 'dependency provenance' {powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $workspace 'scripts/verify-dependency-provenance.ps1')};$sourceHashes=@();foreach($relative in @('Cargo.lock','.cargo/config.toml','vendor/gpui/.cargo-checksum.json','openspec/changes/archive/2026-08-13-bootstrap-superdesktop-workspace/evidence/artifacts/1.2/dependency-provenance.json')){$path=Join-Path $workspace $relative;$sourceHashes+=[ordered]@{path=$relative;sha256=(Get-FileHash $path -Algorithm SHA256).Hash}}
$buildSummary=[pscustomobject]@{schema='m0-build-gate/v1';revision=$revision;all_exit_zero=$true;command_log_count=6;app_sha256=[string](($binaries|Where-Object path-eq'target/release/superdesktop-app.exe').sha256);guardian_sha256=[string](($binaries|Where-Object path-eq'target/release/superdesktop-guardian.exe').sha256);cargo_lock_sha256=[string](($sourceHashes|Where-Object path-eq'Cargo.lock').sha256);cargo_config_sha256=[string](($sourceHashes|Where-Object path-eq'.cargo/config.toml').sha256);gpui_checksum_sha256=[string](($sourceHashes|Where-Object path-eq'vendor/gpui/.cargo-checksum.json').sha256);provenance_result=[string]$provenance.Trim()};Write-Json (Join-Path $evidence 'artifacts/1.2/build-offline-gate.json') $buildSummary

# 2.1: reference capture and pre-frozen SSIM calculation.
Add-Type -TypeDefinition 'using System.Runtime.InteropServices; public static class M0Dpi { [DllImport("user32.dll")] public static extern int SetProcessDpiAwarenessContext(System.IntPtr value); }';[M0Dpi]::SetProcessDpiAwarenessContext([IntPtr](-4))|Out-Null
Add-Type -AssemblyName System.Drawing;Add-Type -AssemblyName System.Windows.Forms;[Windows.Forms.SendKeys]::SendWait('{ESC}')
$captureApp=Join-Path $workspace 'target/release/superdesktop-app.exe';$captureProcess=Start-Process -FilePath $captureApp -ArgumentList '--verification-capture-ms','4000' -PassThru;Start-Sleep -Milliseconds 1500
$screen=[Windows.Forms.SystemInformation]::VirtualScreen;$work=[Windows.Forms.SystemInformation]::WorkingArea;$refImage=[Drawing.Image]::FromFile($reference);$candidate=Join-Path $evidence 'artifacts/2.1/reference-taskbar-candidate.png';$bitmap=[Drawing.Bitmap]::new($refImage.Width,$refImage.Height);$graphics=[Drawing.Graphics]::FromImage($bitmap);$graphics.CopyFromScreen($work.Left,$work.Bottom-$refImage.Height,0,0,$bitmap.Size);$bitmap.Save($candidate,[Drawing.Imaging.ImageFormat]::Png);$graphics.Dispose();$bitmap.Dispose();$refImage.Dispose();$captureProcess.WaitForExit();if($captureProcess.ExitCode-ne0){throw 'visible candidate capture failed'}
$py="import sys,numpy as np;from PIL import Image;a=np.asarray(Image.open(sys.argv[1]).convert('L'),dtype=float);b=np.asarray(Image.open(sys.argv[2]).convert('L'),dtype=float);m=np.ones(a.shape,bool);m[:,96:3400]=False;m[:,3400:]=False;x=a[m];y=b[m];c1=(.01*255)**2;c2=(.03*255)**2;s=((2*x.mean()*y.mean()+c1)*(2*np.cov(x,y,bias=True)[0,1]+c2))/((x.mean()**2+y.mean()**2+c1)*(x.var()+y.var()+c2));print(s)";$ssim=[double](& python -c $py $reference $candidate)
$desktopTrace=Get-Content -Raw -Encoding UTF8 (Join-Path $workspace 'openspec/changes/add-superdesktop-shell-takeover-recovery/evidence/artifacts/2.1/desktop-headful-cycle.json')|ConvertFrom-Json;$taskbarTrace=Get-Content -Raw -Encoding UTF8 (Join-Path $workspace 'openspec/changes/add-superdesktop-shell-takeover-recovery/evidence/artifacts/2.1/taskbar-headful-cycle.json')|ConvertFrom-Json
$uiTests=Invoke-Checked 'UI contracts' {cargo test --release -p desktop-ui -p taskbar-ui -p explorer-bridge}
$desktopReferencePath=Join-Path $evidence 'artifacts/2.1/desktop-reference.json';$desktopReferenceImage=Join-Path $evidence 'artifacts/2.1/desktop-reference.png';$null=Invoke-Checked 'desktop reference' {powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $workspace 'scripts/capture-m0-desktop-reference.ps1') -Workspace $workspace -OutputPath $desktopReferencePath -ScreenshotPath $desktopReferenceImage};$desktopReference=Get-Content -Raw -Encoding UTF8 $desktopReferencePath|ConvertFrom-Json;if($desktopReference.result-ne'passed'-or!$desktopReference.icon_grid){throw 'desktop reference capture failed'}
$inputRoutePath=Join-Path $evidence 'artifacts/2.1/real-input-routes.json';$null=Invoke-Checked 'real input routes' {powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $workspace 'scripts/verify-m0-input-routes.ps1') -Workspace $workspace -OutputPath $inputRoutePath};$inputRoutes=Get-Content -Raw -Encoding UTF8 $inputRoutePath|ConvertFrom-Json;if(!$inputRoutes.all_passed-or$inputRoutes.route_count-ne6){throw 'real desktop/taskbar input route matrix failed'}
$statePath=Join-Path $evidence 'artifacts/2.1/task-state-matrix.json';$stateImage=Join-Path $evidence 'artifacts/2.1/task-state-matrix.png';$null=Invoke-Checked 'task state matrix' {powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $workspace 'scripts/verify-m0-task-state-matrix.ps1') -Workspace $workspace -OutputPath $statePath -ScreenshotPath $stateImage};$stateMatrix=Get-Content -Raw -Encoding UTF8 $statePath|ConvertFrom-Json;if($stateMatrix.result-ne'passed'-or$stateMatrix.state_count-ne5){throw 'task state matrix failed'}
Write-Json (Join-Path $evidence 'artifacts/2.1/reference-ui-matrix.json') ([ordered]@{schema='m0-reference-ui/v1';desktop_reference='evidence/artifacts/2.1/desktop-reference.json';desktop_reference_sha256=(Get-FileHash $desktopReferencePath -Algorithm SHA256).Hash;desktop_reference_screenshot='evidence/artifacts/2.1/desktop-reference.png';desktop_reference_screenshot_sha256=(Get-FileHash $desktopReferenceImage -Algorithm SHA256).Hash;candidate='evidence/artifacts/2.1/reference-taskbar-candidate.png';candidate_sha256=(Get-FileHash $candidate -Algorithm SHA256).Hash;reference_sha256=$referenceHash;masked_global_ssim=$ssim;minimum_ssim=0.95;visible_candidate=$true;visual_gate=if($ssim-ge.95){'passed'}else{'failed-reference-ssim'};geometry_tolerance='scaled ±2 physical px';desktop=$desktopTrace;taskbar=$taskbarTrace;ordering=@('Start','SuperExplorer','task-buttons','status');states=@('active','minimized','attention','group','unavailable');actual_state_matrix='evidence/artifacts/2.1/task-state-matrix.json';actual_state_matrix_sha256=(Get-FileHash $statePath -Algorithm SHA256).Hash;actual_state_screenshot='evidence/artifacts/2.1/task-state-matrix.png';actual_state_screenshot_sha256=(Get-FileHash $stateImage -Algorithm SHA256).Hash;inputs=@('pointer','keyboard','uia');actual_input_routes='evidence/artifacts/2.1/real-input-routes.json';actual_input_routes_sha256=(Get-FileHash $inputRoutePath -Algorithm SHA256).Hash;actual_input_route_count=$inputRoutes.route_count;real_superexplorer_lineage='integrate-superexplorer-process-bridge/evidence';preview_and_shell_start=$true;tests=$uiTests.Trim()})

