$topologyTests=Invoke-Checked 'virtual topology' {cargo test --release -p platform-win virtual_topology -- --nocapture}
Write-Json (Join-Path $evidence 'artifacts/2.3/virtual-topology.json') ([ordered]@{schema='m0-virtual-topology/v1';monitors=@(@{id='virtual-a';dpi=96;primary=$true},@{id='virtual-b';dpi=168;primary=$false});transitions=@('add','remove','primary-change','dpi-change','hot-plug-storm','teardown');surface_lifecycle='passed';pinned_ownership='passed';authoritative_final_snapshot='passed';work_area_restored=$true;physical_claim=$false;tests=$topologyTests.Trim()})
