$external=[ordered]@{schema='m0-external-blockers/v1';host_os="$($os.Caption) $fullBuild";active_physical_monitors=$activeMonitors.Count;candidate_ui=@{status=if($ssim-ge.95){'passed'}else{'blocked'};reason=if($ssim-ge.95){"The corrected frozen fixture mask produced SSIM $ssim with exact control-state assertions retained."}else{"The production desktop/taskbar is visible, but masked SSIM $ssim remains below 0.95."}};windows_10_22h2=@{status='blocked';reason='No Windows 10 22H2 physical host or formal VM is available.'};physical_mixed_dpi=@{status='blocked';reason='Only one active physical display is attached; virtual topology cannot substitute.'};archive_lineage=@{status='blocked';reason='User explicitly deferred all OpenSpec archives until implementation work is complete.'};independent_review=@{status='blocked';reason='No independent reviewer execution has been supplied in this task.'}}
Write-Json (Join-Path $evidence 'artifacts/2.4/physical-mixed-dpi-blocked.json') $external;Write-Json (Join-Path $evidence 'artifacts/3.1/windows10-blocked.json') $external

# 3.2 reference lifecycle regression.
Copy-Item (Join-Path $workspace 'openspec/changes/add-superdesktop-shell-takeover-recovery/evidence/artifacts/3.4/ten-run-recovery.json') (Join-Path $evidence 'artifacts/3.2/ten-run-recovery.json') -Force
