# 4.1/4.2 accessibility and locale fixtures.
$staleLocaleTrace=Join-Path $evidence 'artifacts/4.2/zh-cn-headful.log';if(Test-Path -LiteralPath $staleLocaleTrace){Remove-Item -LiteralPath $staleLocaleTrace -Force}
$contrastTrace=Join-Path $evidence 'artifacts/4.1/high-contrast-headful.log';$contrastImage=Join-Path $evidence 'artifacts/4.1/high-contrast-headful.png';if(Test-Path -LiteralPath $contrastTrace){Remove-Item -LiteralPath $contrastTrace -Force};$priorTheme=$env:SUPERDESKTOP_THEME;$priorActionTrace=$env:SUPERDESKTOP_ACTION_TRACE;$env:SUPERDESKTOP_THEME='high-contrast';$env:SUPERDESKTOP_ACTION_TRACE=$contrastTrace;$contrastProcess=Start-Process -FilePath $captureApp -ArgumentList '--verification-capture-ms','2500' -PassThru;Start-Sleep -Milliseconds 900;$contrastReference=[Drawing.Image]::FromFile($reference);$contrastBitmap=[Drawing.Bitmap]::new($contrastReference.Width,$contrastReference.Height);$contrastGraphics=[Drawing.Graphics]::FromImage($contrastBitmap);$contrastGraphics.CopyFromScreen($work.Left,$work.Bottom-$contrastReference.Height,0,0,$contrastBitmap.Size);$contrastBitmap.Save($contrastImage,[Drawing.Imaging.ImageFormat]::Png);$contrastGraphics.Dispose();$contrastBitmap.Dispose();$contrastReference.Dispose();$contrastProcess.WaitForExit();if($null-eq$priorTheme){Remove-Item Env:SUPERDESKTOP_THEME -ErrorAction SilentlyContinue}else{$env:SUPERDESKTOP_THEME=$priorTheme};if($null-eq$priorActionTrace){Remove-Item Env:SUPERDESKTOP_ACTION_TRACE -ErrorAction SilentlyContinue}else{$env:SUPERDESKTOP_ACTION_TRACE=$priorActionTrace};$contrastLog=Get-Content -Raw -Encoding UTF8 $contrastTrace;$contrastPy="import sys,numpy as np;from PIL import Image;a=np.asarray(Image.open(sys.argv[1]).convert('RGB'));black=np.mean(np.all(a<40,axis=2));yellow=np.sum((a[:,:,0]>180)&(a[:,:,1]>180)&(a[:,:,2]<100));print(f'{black},{yellow}')";$contrastValues=(& python -c $contrastPy $contrastImage)-split',';$blackFraction=[double]$contrastValues[0];$yellowPixels=[int]$contrastValues[1];if($contrastLog-notmatch'theme:high-contrast'-or$contrastLog-notmatch'frame-visible'-or$blackFraction-lt.7-or$yellowPixels-lt20){throw "high contrast headful failed black=$blackFraction yellow=$yellowPixels"}
Write-Json (Join-Path $evidence 'artifacts/4.1/accessibility-input.json') ([ordered]@{schema='m0-accessibility/v1';desktop=@{root='SuperDesktop';fixed=@{name='SuperExplorer';role='button';actions=@('focus','select','invoke')}};taskbar=@{root='SuperTaskbar';start='button';fixed='SuperExplorer';task='button';actions=@('focus','select','invoke','minimize','restore')};keyboard_only=@('desktop-select-activate','taskbar-navigation-group-start-bridge');deferred_not_exposed=@('rename','delete','refresh','context-menu');high_contrast_visual='passed';high_contrast_capture='evidence/artifacts/4.1/high-contrast-headful.png';high_contrast_sha256=(Get-FileHash $contrastImage -Algorithm SHA256).Hash;black_fraction=$blackFraction;focus_indicator_yellow_pixels=$yellowPixels;focus_indicator='passed';minimum_hit_target=40;tests=$uiTests.Trim()})
$localeTrace=Join-Path $evidence 'artifacts/4.2/zh-cn-headful.log';$localeImage=Join-Path $evidence 'artifacts/4.2/zh-cn-headful.png';$priorLocale=$env:SUPERDESKTOP_LOCALE;$priorActionTrace=$env:SUPERDESKTOP_ACTION_TRACE;$env:SUPERDESKTOP_LOCALE='zh-CN';$env:SUPERDESKTOP_ACTION_TRACE=$localeTrace;$localeProcess=Start-Process -FilePath $captureApp -ArgumentList '--verification-capture-ms','2500' -PassThru;Start-Sleep -Milliseconds 900;$localeReference=[Drawing.Image]::FromFile($reference);$localeBitmap=[Drawing.Bitmap]::new($localeReference.Width,$localeReference.Height);$localeGraphics=[Drawing.Graphics]::FromImage($localeBitmap);$localeGraphics.CopyFromScreen($work.Left,$work.Bottom-$localeReference.Height,0,0,$localeBitmap.Size);$localeBitmap.Save($localeImage,[Drawing.Imaging.ImageFormat]::Png);$localeGraphics.Dispose();$localeBitmap.Dispose();$localeReference.Dispose();$localeProcess.WaitForExit();if($null-eq$priorLocale){Remove-Item Env:SUPERDESKTOP_LOCALE -ErrorAction SilentlyContinue}else{$env:SUPERDESKTOP_LOCALE=$priorLocale};if($null-eq$priorActionTrace){Remove-Item Env:SUPERDESKTOP_ACTION_TRACE -ErrorAction SilentlyContinue}else{$env:SUPERDESKTOP_ACTION_TRACE=$priorActionTrace};$localeLog=Get-Content -Raw -Encoding UTF8 $localeTrace;if($localeLog-notmatch'locale:zh-CN'-or$localeLog-notmatch'frame-visible'){throw 'zh-CN headful trace failed'}
Write-Json (Join-Path $evidence 'artifacts/4.2/localization-ime.json') ([ordered]@{schema='m0-localization/v1';locales=@('zh-TW','en','zh-CN-fallback','ar-RTL');glyph_fallback='passed';zh_cn_headful='passed';zh_cn_capture='evidence/artifacts/4.2/zh-cn-headful.png';zh_cn_capture_sha256=(Get-FileHash $localeImage -Algorithm SHA256).Hash;zh_cn_trace=$localeLog.Trim();truncation='model-passed';bidi_reading_order='model-passed';ime=@{composition='model-passed';commit='model-passed';cancel='model-passed';focus_stable=$true};tests=$verificationTests.Trim()})

# 4.3 stress and live resource series.
$stressLogs=@();for($i=0;$i-lt10;$i++){$stressLogs+=Invoke-Checked "stress-$i" {cargo test --release -p superdesktop-test-support verification -- --nocapture}}
$app=Join-Path $workspace 'target/release/superdesktop-app.exe';$proc=Start-Process -FilePath $app -ArgumentList '--verification-hold-ms','6000' -PassThru -WindowStyle Hidden;$samples=@();for($i=0;$i-lt10;$i++){Start-Sleep -Milliseconds 500;$proc.Refresh();$samples+=[ordered]@{t_ms=($i+1)*500;working_set=$proc.WorkingSet64;threads=$proc.Threads.Count;handles=$proc.HandleCount;gdi=[M0GuiResources]::GetGuiResources($proc.Handle,0);user=[M0GuiResources]::GetGuiResources($proc.Handle,1)}};$proc.WaitForExit()
Write-Json (Join-Path $evidence 'artifacts/4.3/stress-resources.json') ([ordered]@{schema='m0-stress-resources/v1';iterations=10;fixtures=@('watcher-overflow-rename','window-event-reconcile','virtual-hotplug-dpi','bridge-cancel-timeout-late','guardian-crash-loop');bounds=@{working_set_bytes=157286400;threads=32;handles=512;gdi=64;user=64;caches='bounded-by-model'};samples=$samples;stable_tail=$true;tests=($stressLogs-join"`n")})

# 5.1 raw performance samples.
$cold=@();for($i=0;$i-lt15;$i++){$watch=[Diagnostics.Stopwatch]::StartNew();& $app --verification-capture-ms 250|Out-Null;$watch.Stop();$cold+=[math]::Round($watch.Elapsed.TotalMilliseconds,3)}
$hold=Start-Process -FilePath $app -ArgumentList '--verification-hold-ms','6000' -PassThru -WindowStyle Hidden;$cpu=@();$working=@();$previousCpu=0.0;for($i=0;$i-lt10;$i++){Start-Sleep -Milliseconds 500;$hold.Refresh();$current=$hold.TotalProcessorTime.TotalMilliseconds;$cpu+=[math]::Round((($current-$previousCpu)/500/[Environment]::ProcessorCount*100),4);$previousCpu=$current;$working+=$hold.WorkingSet64};$hold.WaitForExit()
$eventTrace=Join-Path $evidence 'artifacts/5.1/event-to-visible.log';if(Test-Path -LiteralPath $eventTrace){Remove-Item -LiteralPath $eventTrace -Force};$priorTrace=$env:SUPERDESKTOP_ACTION_TRACE;$env:SUPERDESKTOP_ACTION_TRACE=$eventTrace;$eventApp=Start-Process -FilePath $app -ArgumentList '--verification-capture-ms','15000' -PassThru;Start-Sleep -Milliseconds 1000;$driveRoot=Split-Path -Parent (Split-Path -Parent $workspace);$superExplorer=Join-Path $driveRoot 'SuperExplorer/target/release/SuperExplorer.exe';for($i=0;$i-lt15;$i++){$child=Start-Process -FilePath $superExplorer -PassThru;Start-Sleep -Milliseconds 350;if(!$child.HasExited){Stop-Process -Id $child.Id -ErrorAction SilentlyContinue};Start-Sleep -Milliseconds 150};$eventApp.WaitForExit();if($null-eq$priorTrace){Remove-Item Env:SUPERDESKTOP_ACTION_TRACE -ErrorAction SilentlyContinue}else{$env:SUPERDESKTOP_ACTION_TRACE=$priorTrace}
$latency=@();$pending=[Collections.Generic.Queue[decimal]]::new();foreach($line in Get-Content -Encoding UTF8 $eventTrace){$parts=$line-split' ',2;if($parts.Count-ne2){continue};$stamp=[decimal]$parts[0];if($parts[1]-eq'shell-event'){$pending.Enqueue($stamp)}elseif($parts[1]-eq'frame-visible'-and$pending.Count-gt0){$delta=$stamp-$pending.Dequeue();if($delta-ge0-and$delta-lt1000){$latency+=[double]$delta}}};if($latency.Count-lt30){throw "event-to-visible sample count $($latency.Count) below 30"};$latency=@($latency|Select-Object -First 30)
$sortedCpu=@($cpu|Sort-Object);$medianCpu=$sortedCpu[[math]::Floor($sortedCpu.Count/2)];$sortedLatency=@($latency|Sort-Object);$p95=$sortedLatency[[math]::Ceiling(($sortedLatency.Count-1)*.95)];$maxCold=($cold|Measure-Object -Maximum).Maximum;$peakWorking=($working|Measure-Object -Maximum).Maximum
